ST.xhtml:
IF NOT(superState) THEN
    F_DomeShutterOpeningStatus := DomeShutterOpeningStatus.unknown;
ELSIF shutterValue = DomeShutterMotionStates.STANDSTILL THEN
    F_DomeShutterOpeningStatus := DomeShutterOpeningStatus.standstill;
ELSIF shutterValue = DomeShutterMotionStates.OPENING THEN
    F_DomeShutterOpeningStatus := DomeShutterOpeningStatus.opening;
ELSIF shutterValue = DomeShutterMotionStates.CLOSING THEN
    F_DomeShutterOpeningStatus := DomeShutterOpeningStatus.closing;
ELSIF shutterValue = DomeShutterMotionStates.STOPPING THEN
    F_DomeShutterOpeningStatus := DomeShutterOpeningStatus.stopping;
ELSIF shutterValue = DomeShutterMotionStates.TIMEOUT_ERROR THEN
    F_DomeShutterOpeningStatus := DomeShutterOpeningStatus.timeoutError;
ELSIF shutterValue = DomeShutterMotionStates.RETRY_OPENING THEN
    F_DomeShutterOpeningStatus := DomeShutterOpeningStatus.retryOpening;
ELSIF shutterValue = DomeShutterMotionStates.RETRY_CLOSING THEN
    F_DomeShutterOpeningStatus := DomeShutterOpeningStatus.retryClosing;
ELSIF shutterValue = DomeShutterMotionStates.UNKNOWN_DRIVE_LOGIC_ERROR THEN
    F_DomeShutterOpeningStatus := DomeShutterOpeningStatus.unknownDriveLogicError;
ELSE
    F_DomeShutterOpeningStatus := DomeShutterOpeningStatus.invalid_model;
END_IF;

parts.shutter(
    init_ref := stat.init,
    operator_ref := operator_ref,
    operating_ref := stat.operating,
    activity_ref := activity_ref,
    config_ref := config_ref.shutter,
    services_ref := services_ref);
parts.rotation(
    init_ref := stat.init,
    operator_ref := operator_ref,
    operating_ref := stat.operating,
    config_ref := config_ref.rotation);
stat.health := F_HealthStatus(
    superState := TRUE,
    isGood := (NOT(stat.init = InitializationStatus.initializingFailed)) AND (((parts.shutter.stat.health = HealthStatus.good) OR (parts.shutter.stat.health = HealthStatus.warning)) AND (((parts.rotation.stat.health = HealthStatus.good) OR (parts.rotation.stat.health = HealthStatus.warning)) AND (((proc.reset.stat.health = HealthStatus.good) OR (proc.reset.stat.health = HealthStatus.warning)) AND (((proc.initialize.stat.health = HealthStatus.good) OR (proc.initialize.stat.health = HealthStatus.warning)) AND (((proc.syncWithAxes.stat.health = HealthStatus.good) OR (proc.syncWithAxes.stat.health = HealthStatus.warning)) AND (((proc.startTrackingTelescope.stat.health = HealthStatus.good) OR (proc.startTrackingTelescope.stat.health = HealthStatus.warning)) AND (((proc.stopTrackingTelescope.stat.health = HealthStatus.good) OR (proc.stopTrackingTelescope.stat.health = HealthStatus.warning)) AND (((proc.stop.stat.health = HealthStatus.good) OR (proc.stop.stat.health = HealthStatus.warning)) AND ((proc.moveKnownPosition.stat.health = HealthStatus.good) OR (proc.moveKnownPosition.stat.health = HealthStatus.warning)))))))))),
    hasWarning := (parts.shutter.stat.health = HealthStatus.warning) OR ((parts.rotation.stat.health = HealthStatus.warning) OR ((proc.reset.stat.health = HealthStatus.warning) OR ((proc.initialize.stat.health = HealthStatus.warning) OR ((proc.syncWithAxes.stat.health = HealthStatus.warning) OR ((proc.startTrackingTelescope.stat.health = HealthStatus.warning) OR ((proc.stopTrackingTelescope.stat.health = HealthStatus.warning) OR ((proc.stop.stat.health = HealthStatus.warning) OR (proc.moveKnownPosition.stat.health = HealthStatus.warning)))))))));
stat.busy := F_BusyStatus(
    superState := TRUE,
    isBusy := (parts.shutter.stat.busy = BusyStatus.busy) OR ((parts.rotation.stat.busy = BusyStatus.busy) OR ((proc.reset.stat.busy = BusyStatus.busy) OR ((proc.initialize.stat.busy = BusyStatus.busy) OR ((proc.syncWithAxes.stat.busy = BusyStatus.busy) OR ((proc.startTrackingTelescope.stat.busy = BusyStatus.busy) OR ((proc.stopTrackingTelescope.stat.busy = BusyStatus.busy) OR ((proc.stop.stat.busy = BusyStatus.busy) OR (proc.moveKnownPosition.stat.busy = BusyStatus.busy)))))))));
proc.initialize( isEnabled := (NOT(stat.init = InitializationStatus.locked)) AND ((stat.init = InitializationStatus.shutdown) OR ((stat.init = InitializationStatus.initializingFailed) OR (stat.init = InitializationStatus.initialized))) );
proc.changeOperatingState( isEnabled := FALSE );
proc.lock( isEnabled := operator_ref = OperatorStatus.tech );
proc.unlock( isEnabled := (operator_ref = OperatorStatus.tech) AND (stat.init = InitializationStatus.locked) );
proc.reset( isEnabled := (stat.busy = BusyStatus.idle) AND (stat.init = InitializationStatus.initialized) );
proc.syncWithAxes( isEnabled := (stat.init = InitializationStatus.initialized) AND (stat.busy = BusyStatus.idle) );
proc.startTrackingTelescope( isEnabled := NOT(isTrackingTelescope) );
proc.stopTrackingTelescope( isEnabled := isTrackingTelescope );
proc.moveAbsolute( isEnabled := stat.init = InitializationStatus.initialized );
proc.stop( isEnabled := (stat.busy = BusyStatus.busy) OR (isTrackingTelescope OR (operator_ref = OperatorStatus.tech)) );
proc.moveKnownPosition( isEnabled := (stat.init = InitializationStatus.initialized) AND (stat.busy = BusyStatus.idle) );

stat.aperture := F_ApertureStatus(
    superState := NOT((dataRead.apertureState = DomeShutterApertureStates.UNKNOWN) OR (dataRead.apertureState = DomeShutterApertureStates.INVALID)),
    isOpen := dataRead.apertureState = DomeShutterApertureStates.FULLY_OPEN,
    isClosed := dataRead.apertureState = DomeShutterApertureStates.FULLY_CLOSED);
stat.motion := F_DomeShutterOpeningStatus(
    superState := TRUE,
    shutterValue := dataRead.motionState);
stat.health := F_HealthStatus(
    superState := NOT(init_ref = InitializationStatus.shutdown),
    isGood := isConnected AND ((NOT(stat.aperture = ApertureStatus.undefined)) AND (((proc.open.stat.health = HealthStatus.good) OR (proc.open.stat.health = HealthStatus.warning)) AND (((proc.close.stat.health = HealthStatus.good) OR (proc.close.stat.health = HealthStatus.warning)) AND ((proc.stop.stat.health = HealthStatus.good) OR (proc.stop.stat.health = HealthStatus.warning))))),
    hasWarning := ((proc.open.stat.health = HealthStatus.warning) OR ((proc.close.stat.health = HealthStatus.warning) OR (proc.stop.stat.health = HealthStatus.warning))) OR ((stat.busy = BusyStatus.idle) AND (stat.aperture = ApertureStatus.partiallyOpen)));
stat.busy := F_BusyStatus(
    superState := NOT(init_ref = InitializationStatus.shutdown),
    isBusy := (proc.open.stat.busy = BusyStatus.busy) OR ((proc.close.stat.busy = BusyStatus.busy) OR (proc.stop.stat.busy = BusyStatus.busy)));
proc.open( isEnabled := (stat.health = HealthStatus.good) AND ((NOT(init_ref = InitializationStatus.locked)) AND ((operator_ref = OperatorStatus.tech) OR ((stat.busy = BusyStatus.idle) AND (init_ref = InitializationStatus.initialized)))) );
proc.close( isEnabled := (operator_ref = OperatorStatus.tech) OR ((NOT(init_ref = InitializationStatus.locked)) AND ((stat.busy = BusyStatus.idle) AND (init_ref = InitializationStatus.initialized))) );
proc.stop( isEnabled := stat.busy = BusyStatus.busy );
proc.send( isEnabled := (operator_ref = OperatorStatus.tech) OR isConnected );

stat.health := F_HealthStatus(
    superState := TRUE,
    isGood := isSimulated OR ((NOT(power)) OR (NOT(dataError OR (frameError OR (powerFailure OR (dataMismatch OR syncError)))))));
stat.busy := F_BusyStatus(
    superState := TRUE,
    isBusy := (proc.powerOn.stat.busy = BusyStatus.busy) OR (proc.powerOff.stat.busy = BusyStatus.busy));
proc.powerOn( isEnabled := NOT(stat.busy = BusyStatus.busy) );
proc.powerOff( isEnabled := NOT(stat.busy = BusyStatus.busy) );

parts.motorAxis( isEnabled := (NOT(init_ref = InitializationStatus.locked)) AND (operator_ref = OperatorStatus.tech) );
parts.encoderAxis( isEnabled := (NOT(init_ref = InitializationStatus.locked)) AND (operator_ref = OperatorStatus.tech) );
stat.health := F_HealthStatus(
    superState := TRUE,
    isGood := ((parts.motorAxis.stat.health = HealthStatus.good) OR (parts.motorAxis.stat.health = HealthStatus.warning)) AND (((parts.encoderAxis.stat.health = HealthStatus.good) OR (parts.encoderAxis.stat.health = HealthStatus.warning)) AND (((proc.moveAbsolute.stat.health = HealthStatus.good) OR (proc.moveAbsolute.stat.health = HealthStatus.warning)) AND (((proc.reset.stat.health = HealthStatus.good) OR (proc.reset.stat.health = HealthStatus.warning)) AND ((proc.stop.stat.health = HealthStatus.good) OR (proc.stop.stat.health = HealthStatus.warning))))),
    hasWarning := (parts.motorAxis.stat.health = HealthStatus.warning) OR ((parts.encoderAxis.stat.health = HealthStatus.warning) OR ((proc.moveAbsolute.stat.health = HealthStatus.warning) OR ((proc.reset.stat.health = HealthStatus.warning) OR (proc.stop.stat.health = HealthStatus.warning)))));
stat.busy := F_BusyStatus(
    superState := TRUE,
    isBusy := (parts.motorAxis.stat.busy = BusyStatus.busy) OR ((parts.encoderAxis.stat.busy = BusyStatus.busy) OR ((proc.moveAbsolute.stat.busy = BusyStatus.busy) OR ((proc.reset.stat.busy = BusyStatus.busy) OR (proc.stop.stat.busy = BusyStatus.busy)))));
proc.reset( isEnabled := stat.busy = BusyStatus.idle );
proc.stop( isEnabled := (stat.busy = BusyStatus.busy) OR (operator_ref = OperatorStatus.tech) );
proc.moveAbsolute( isEnabled := stat.busy = BusyStatus.idle );

IF do_request THEN
    do_request_result := request( name := set.name );
    do_request := FALSE;
END_IF;
SUPER^();

THIS^.get.name := name;
THIS^.stat.busy := BusyStatus.busy;
THIS^.stat.health := HealthStatus.good;

IF THIS^.stat.enabled = EnabledStatus.enabled THEN
    request := RequestResults.ACCEPTED;
    THIS^.start( name := name );
ELSE
    request := RequestResults.REJECTED;
END_IF;

IF do_request THEN
    do_request_result := request( position := set.position );
    do_request := FALSE;
END_IF;
SUPER^();

THIS^.get.position := position;
THIS^.stat.busy := BusyStatus.busy;
THIS^.stat.health := HealthStatus.good;

IF THIS^.stat.enabled = EnabledStatus.enabled THEN
    request := RequestResults.ACCEPTED;
    THIS^.start( position := position );
ELSE
    request := RequestResults.REJECTED;
END_IF;

IF do_request THEN
    do_request_result := request(
    command := set.command,
    arg := set.arg);
    do_request := FALSE;
END_IF;
SUPER^();

THIS^.get.command := command;
THIS^.get.arg := arg;
THIS^.stat.busy := BusyStatus.busy;
THIS^.stat.health := HealthStatus.good;

IF THIS^.stat.enabled = EnabledStatus.enabled THEN
    request := RequestResults.ACCEPTED;
    THIS^.start(
        command := command,
        arg := arg);
ELSE
    request := RequestResults.REJECTED;
END_IF;
